/* Organisation-name matchers, most specific first. */
var MATCHERS = [
	[ /\basustek\b|\basus\b/i, 'asus' ],
	[ /xiaomi/i, 'xiaomi' ],
	[ /\bapple\b/i, 'apple' ],
	[ /samsung/i, 'samsung' ],
	[ /\bintel\b/i, 'intel' ],
	[ /huawei/i, 'huawei' ],
	[ /mediatek/i, 'mediatek' ],
	[ /qualcomm/i, 'qualcomm' ],
	[ /tp-?link/i, 'tplink' ],
	[ /netgear/i, 'netgear' ],
	[ /mikrotik/i, 'mikrotik' ],
	[ /ubiquiti/i, 'ubiquiti' ],
	[ /\bhp\b|hewlett/i, 'hp' ],
	[ /\bdell\b/i, 'dell' ],
	[ /lenovo/i, 'lenovo' ],
	[ /\bsony\b/i, 'sony' ],
	[ /\blg\b/i, 'lg' ],
	[ /oneplus/i, 'oneplus' ],
	[ /\boppo\b/i, 'oppo' ],
	[ /\bvivo\b/i, 'vivo' ],
	[ /motorola/i, 'motorola' ],
	[ /\bgoogle\b/i, 'google' ],
	[ /\bsonos\b/i, 'sonos' ],
	[ /siemens/i, 'siemens' ],
	[ /\bbosch\b/i, 'bosch' ],
	[ /panasonic/i, 'panasonic' ],
	[ /\bsharp\b/i, 'sharp' ],
	[ /toshiba/i, 'toshiba' ],
	[ /fujitsu/i, 'fujitsu' ],
	[ /raspberry\s*pi/i, 'raspberrypi' ],
	[ /espressif/i, 'espressif' ],
	[ /\bvmware\b/i, 'vmware' ],
	[ /synology/i, 'synology' ],
	[ /\bqnap\b/i, 'qnap' ],
	[ /\bhonor\b/i, 'honor' ],
	[ /\bmeizu\b/i, 'meizu' ],
	[ /\bnokia\b/i, 'nokia' ],
	[ /\bcisco\b/i, 'cisco' ],
	[ /\bfortinet\b/i, 'fortinet' ],
	[ /\bamd\b|advanced micro devices/i, 'amd' ],
	[ /nvidia/i, 'nvidia' ],
	[ /broadcom/i, 'broadcom' ],
];

function clean(value) {
	return typeof value === 'string' ? value.trim() : '';
}

function brandFor(name) {
	var text = clean(name);
	if (!text)
		return null;
	for (var i = 0; i < MATCHERS.length; i++) {
		if (MATCHERS[i][0].test(text))
			return BRANDS[MATCHERS[i][1]] || null;
	}
	return null;
}

function initials(name) {
	var words = clean(name).split(/[^A-Za-z0-9]+/).filter(function(word) {
		return word.length > 0;
	});
	if (words.length === 0)
		return '?';
	if (words.length === 1)
		return words[0].slice(0, 2).toUpperCase();
	return (words[0].charAt(0) + words[1].charAt(0)).toUpperCase();
}

function svgNode(brand) {
	var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
	svg.setAttribute('viewBox', '0 0 24 24');
	svg.setAttribute('aria-hidden', 'true');
	svg.setAttribute('focusable', 'false');
	var path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
	path.setAttribute('d', brand.path);
	svg.appendChild(path);
	return svg;
}

/*
 * Builds the small square mark shown in front of an organisation name.
 * state is one of vendor | unknown | local | loading | unavailable, which
 * only decides the fallback letter and the tone of the chip.
 */
function logoNode(name, state) {
	var brand = state === 'vendor' ? brandFor(name) : null;
	var chip = document.createElement('span');
	chip.className = 'lanspeed-vendor-logo';
	if (brand) {
		chip.setAttribute('data-vendor-logo', 'brand');
		chip.setAttribute('data-vendor-tone', brand.tone);
		chip.style.setProperty('--vendor-brand', brand.color);
		chip.title = brand.name;
		chip.appendChild(svgNode(brand));
		return chip;
	}

	var letter = state === 'local' ? '?' : (state === 'loading' ? '' : initials(name));
	chip.setAttribute('data-vendor-logo', state === 'local' ? 'local' : (state === 'loading' ? 'loading' : 'letter'));
	chip.className = 'lanspeed-vendor-logo lanspeed-vendor-logo--text';
	if (letter)
		chip.textContent = letter;
	return chip;
}

return baseclass.extend({
	brand: brandFor,
	initials: initials,
	logo: logoNode
});
